DI void prob(float (&s)[NK/8][4],float (&m)[2],float (&ls)[2],float (&alpha)[2],uint32_t (&pk)[NK/8],float sc,int key0,int seq,int end,int window) {
  constexpr int H=8/QT,N=NK/8;
