    for(int n=0;n<N;n++)for(int e=0;e<2;e++) {
      const int key=key0+8*n+2*t+e;
      const bool valid=live && key<end && key<=seq+tok && key>=seq+tok-window+1;
      const float v=valid?s[n][2*rh+e]*sc:-INFINITY;
