 for(int rh=0;rh<2;++rh){stats[tid*6+rh]=m[rh];stats[tid*6+2+rh]=l[rh];stats[tid*6+4+rh]=alpha[rh];}
 for(int n=0;n<8;++n)for(int e=0;e<4;++e)oo[tid*32+n*4+e]=o[n][e];
}
