  if constexpr(FM==2){int rem=min(count-row,32);if(rem<=LO||rem>HI)continue;}
  int src[NJ];
  #pragma unroll
  for(int j=0;j<NJ;++j){int rl=t/8+j*16,r=row+rl;src[j]=(rl<NT&&r<count)?(FIRST?SLOTS[e*M+r]/8:offset+r):-1;}
  float acc[NT/2]={};unsigned af[2][16]={};
