 asm("lop3.b32 %0,%1,0x0ff00ff0,%2,0xea;":"=r"(odd):"r"(rot),"r"(scale_base));
 unsigned s0=__byte_perm(even,even,0x1010),s2=__byte_perm(even,even,0x3232);
 unsigned s1=__byte_perm(odd,odd,0x1010),s3=__byte_perm(odd,odd,0x3232);
