 else if(k==NS-2)asm volatile("cp.async.wait_group 1;":::"memory");
 else asm volatile("cp.async.wait_group %0;"::"n"(S-2):"memory");
}
template<int NT>constexpr int smem_bytes(){return 1023+((S*(64*KT/2+64*KT/16)+1023)&~1023)+S*NT*KT*2;}

