    auto k = glue_cl::boundary_cl<C_, NT_, R_>;                                                              \
    glue_cl::set_attrs(k);                                                                                   \
    e = glue_cl::launch(k, C, NT, (int)T, s, (const void*)P, (int)pf32, (int)S, (long long)ps, (long long)rs, \
                        (int)NB, (const float*)stream, (float*)sout, (__nv_bfloat16*)out, (const float*)postw,   \
